  insert into lessons (unit_id, position, title, kind, body, est_minutes) values (u_id,1,'Bijzinnen met omdat, dat en als','grammar',$j${"intro": "Je leert hoe de persoonsvorm in een bijzin naar het einde van de zin gaat.", "vocab": ["verhuizen", "sleutel", "binnenkomen", "het druk hebben"], "sections": [{"type": "text", "title": "Hoofdzin en bijzin", "paragraphs": ["In een hoofdzin staat de persoonsvorm op de tweede plaats: Ik werk vandaag thuis.", "In een bijzin gaat de persoonsvorm naar het einde van de zin. Een bijzin begint met een voegwoord, bijvoorbeeld omdat, dat, als of terwijl.", "Als de bijzin voorop staat, begint de hoofdzin daarna met de persoonsvorm: Als het regent, blijf ik thuis."], "examples": [{"nl": "Ik werk thuis, omdat ons kantoor verhuist.", "note": "De persoonsvorm verhuist staat aan het einde."}, {"nl": "Ik weet dat zij vandaag niet werkt.", "note": "Na dat staat het onderwerp, dan de rest, dan de persoonsvorm."}, {"nl": "Hij komt niet binnen, omdat hij zijn sleutel niet kan vinden.", "note": "Kan staat voor de infinitief vinden. Beide staan aan het einde."}, {"nl": "Als het morgen regent, blijf ik thuis.", "note": "Na de bijzin komt eerst de persoonsvorm blijf."}, {"wrong": "Ik blijf thuis omdat ik ben moe.", "nl": "Ik blijf thuis omdat ik moe ben.", "note": "Een veelgemaakte fout: de persoonsvorm ben moet aan het einde staan."}]}, {"type": "exercises", "items": [{"kind": "mcq", "tag": "bijzin-woordvolgorde", "prompt": "Kies de juiste zin.", "options": ["Ik blijf thuis omdat ik ben moe.", "Ik blijf thuis omdat ik moe ben.", "Ik blijf thuis omdat moe ik ben."], "answer": 1, "explanation": "In een bijzin staat de persoonsvorm ben aan het einde."}, {"kind": "mcq", "tag": "bijzin-woordvolgorde", "prompt": "Kies de juiste zin.", "options": ["Ik weet dat zij vandaag niet werkt.", "Ik weet dat zij werkt vandaag niet.", "Ik weet dat werkt zij vandaag niet."], "answer": 0, "explanation": "Na dat staat de persoonsvorm werkt aan het einde."}, {"kind": "gap", "tag": "inversie", "prompt": "Als het morgen regent, ___ ik thuis.", "answers": ["blijf"], "explanation": "Na een voorop staande bijzin komt de persoonsvorm direct daarna: blijf ik."}, {"kind": "gap", "tag": "bijzin-modaal", "prompt": "Hij komt niet binnen, omdat hij zijn sleutel niet kan ___.", "answers": ["vinden"], "explanation": "Kan en vinden staan aan het einde. De infinitief staat achter kan."}, {"kind": "gap", "tag": "bijzin-woordvolgorde", "prompt": "Ik zie dat jij het erg druk ___.", "answers": ["hebt"], "explanation": "Bij jij gebruik je hebt. De persoonsvorm staat aan het einde van de bijzin."}]}]}$j$::jsonb,12) on conflict (unit_id, position) do nothing;
  insert into lessons (unit_id, position, title, kind, body, est_minutes) values (u_id,2,'Een gesprek op kantoor','listening',$j${"intro": "Je luistert naar een gesprek op kantoor en leert vijf natuurlijke uitdrukkingen.", "vocab": ["planning", "overnemen", "afspraak", "gemeente", "doornemen", "opsturen", "Dat komt goed uit", "Dat ligt eraan", "Zeg het maar", "Dan red ik dat wel", "Ik heb er zin in"], "sections": [{"type": "dialogue", "title": "Over de planning", "lines": [{"speaker": "Sanne", "voice": "fenna", "text": "Goedemorgen, Mark. Heb je even tijd?"}, {"speaker": "Mark", "voice": "maarten", "text": "Ja hoor, zeg het maar."}, {"speaker": "Sanne", "voice": "fenna", "text": "Ik wil het over de planning van volgende week hebben."}, {"speaker": "Mark", "voice": "maarten", "text": "Dat komt goed uit. Ik wilde jou ook al iets vragen."}, {"speaker": "Sanne", "voice": "fenna", "text": "Kun je donderdag de presentatie overnemen? Ik heb een afspraak bij de gemeente."}, {"speaker": "Mark", "voice": "maarten", "text": "Dat ligt eraan. Hoe laat begint de presentatie?"}, {"speaker": "Sanne", "voice": "fenna", "text": "Om half tien."}, {"speaker": "Mark", "voice": "maarten", "text": "Dan red ik dat wel. Ik heb er eigenlijk wel zin in."}, {"speaker": "Sanne", "voice": "fenna", "text": "Fijn. Ik stuur je vanmiddag de slides op."}, {"speaker": "Mark", "voice": "maarten", "text": "Top, dan neem ik ze vanavond door."}], "expressions": [{"nl": "Zeg het maar", "meaning_nl": "Je mag beginnen met praten of vragen.", "register": "informeel, gesproken"}, {"nl": "Dat komt goed uit", "meaning_nl": "Dat past mij goed.", "register": "neutraal, gesproken"}, {"nl": "Dat ligt eraan", "meaning_nl": "Het hangt van iets af. Daarna noem je meestal de voorwaarde.", "register": "neutraal"}, {"nl": "Dan red ik dat wel", "meaning_nl": "Dan lukt het mij wel.", "register": "informeel, gesproken"}, {"nl": "Ik heb er zin in", "meaning_nl": "Ik kijk ernaar uit en vind het leuk.", "register": "informeel"}]}, {"type": "exercises", "items": [{"kind": "mcq", "tag": "luisteren", "prompt": "Waarom wil Sanne dat Mark de presentatie overneemt?", "options": ["Ze is ziek.", "Ze heeft een afspraak bij de gemeente.", "Ze gaat op vakantie."], "answer": 1, "explanation": "Sanne zegt: Ik heb een afspraak bij de gemeente."}, {"kind": "mcq", "tag": "luisteren", "prompt": "Hoe laat begint de presentatie?", "options": ["Half negen", "Half tien", "Tien uur"], "answer": 1, "explanation": "Om half tien."}, {"kind": "mcq", "tag": "luisteren", "prompt": "Wanneer stuurt Sanne de slides?", "options": ["Vanochtend", "Vanmiddag", "Donderdag"], "answer": 1, "explanation": "Ik stuur je vanmiddag de slides op."}, {"kind": "gap", "tag": "uitdrukking", "prompt": "Dan ___ ik dat wel.", "answers": ["red"], "explanation": "De uitdrukking is: Dan red ik dat wel."}, {"kind": "dictation", "tag": "dictee", "text": "Dat ligt eraan.", "voice": "maarten", "explanation": "Schrijf precies wat je hoort."}]}]}$j$::jsonb,15) on conflict (unit_id, position) do nothing;
  insert into lessons (unit_id, position, title, kind, body, est_minutes) values (u_id,3,'Natuurlijk Nederlands: reageren op collega''s','vocabulary',$j${"intro": "Je vergelijkt schoolboek-Nederlands met natuurlijk gesproken Nederlands.", "vocab": ["vergadering", "bespreken", "eigenlijk", "Dat valt wel mee", "Ik zie het wel", "Daar ben ik het mee eens", "Hoe bedoel je precies?"], "sections": [{"type": "text", "title": "Schoolboek of natuurlijk?", "paragraphs": ["Zinnen uit een leerboek zijn correct, maar mensen praten vaak anders. Hieronder zie je beide versies. Gebruik de natuurlijke versie in gesprekken met collega's en vrienden. Schrijf in formele brieven liever de standaardvorm."], "examples": [{"wrong": "Ik weet het nog niet.", "nl": "Ik zie het wel.", "note": "Informeel. Je beslist later."}, {"wrong": "Ik ben het met u eens.", "nl": "Daar ben ik het mee eens.", "note": "Gewoon gesproken Nederlands. Daar staat voorop en mee komt aan het einde."}, {"wrong": "Dat is niet zo moeilijk.", "nl": "Dat valt wel mee.", "note": "Informeel. Het is minder erg dan je dacht."}, {"wrong": "Wat bedoelt u?", "nl": "Hoe bedoel je precies?", "note": "Neutraal en beleefd genoeg voor collega's."}]}, {"type": "exercises", "items": [{"kind": "mcq", "tag": "uitdrukking", "prompt": "Een collega vraagt: Kom je morgen naar de vergadering? Je weet het nog niet. Wat zeg je?", "options": ["Dat valt wel mee.", "Ik zie het wel.", "Daar ben ik het mee eens."], "answer": 1, "explanation": "Ik zie het wel betekent dat je later beslist."}, {"kind": "mcq", "tag": "uitdrukking", "prompt": "Iemand vraagt of je nieuwe baan zwaar is. Je vindt het niet erg. Wat zeg je?", "options": ["Dat valt wel mee.", "Ik heb er zin in.", "Zeg het maar."], "answer": 0, "explanation": "Dat valt wel mee betekent dat iets minder erg is dan verwacht."}, {"kind": "gap", "tag": "uitdrukking", "prompt": "Daar ben ik het ___ eens.", "answers": ["mee"], "explanation": "Het is eens zijn met iets: daar ben ik het mee eens."}, {"kind": "gap", "tag": "uitdrukking", "prompt": "Dat ___ wel mee.", "answers": ["valt"], "explanation": "De vaste uitdrukking is: Dat valt wel mee."}, {"kind": "dictation", "tag": "dictee", "text": "Ik zie het wel.", "voice": "fenna", "explanation": "Schrijf precies wat je hoort."}]}]}$j$::jsonb,12) on conflict (unit_id, position) do nothing;
